mapper.select:
select * from (
    select  ,
    b.machine_name as lh_machine_name,
    c.GENERAGE_DATE as schedule_date
    from t_lh_mold_change_plan a left join t_lh_machine_info b on a.lh_machine_code=b.machine_code and b.del_flag ='0'
    left join T_MOLD_AUTO_GENERAGE_RECORD c on a.MOLD_BATCH_NO = c.MOLD_BATCH_NO and c.STATUS = '0' and c.del_flag = '0'

        a.del_flag ='0'
        and a.mold_batch_no = #{moldBatchNo}
        and a.lh_machine_code = #{lhMachineCode}
        and a.lh_machine_name like concat(concat('%',
            #{lhMachineName}), '%')

        and a.before_spec_desc = #{beforeSpecDesc}
        and a.tire_rough_stock = #{tireRoughStock}
        and a.change_type = #{changeType}
        and a.after_sap_code = #{afterSapCode}
        and a.after_spec_desc = #{afterSpecDesc}
        and a.stock_area = #{stockArea}
        and a.change_time = #{changeTime}
        and c.GENERAGE_DATE = #{scheduleDate}
        and a.is_release = #{isRelease}


        order by a.CHANGE_TIME

) t

    order by ${orderStr}

mapper.update:
update t_lh_mold_change_plan
mold_batch_no = #{moldBatchNo}, lh_machine_code = #{lhMachineCode}, lh_machine_name = #{lhMachineName}, before_sap_code = #{beforeSapCode}, before_spec_desc = #{beforeSpecDesc}, tire_rough_stock = #{tireRoughStock,jdbcType=DECIMAL}, change_type = #{changeType}, after_sap_code = #{afterSapCode}, after_spec_desc = #{afterSpecDesc}, stock_area = #{stockArea}, change_time = #{changeTime}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, remark = #{remark},
where id = #{id}

mapper.insert:
INSERT INTO MES_MOLD_CHANGE_PLAN (MOLD_BATCH_NO, LH_MACHINE_CODE, LH_MACHINE_NAME, BEFORE_SAP_CODE, BEFORE_SPEC_DESC, TIRE_ROUGH_STOCK, CHANGE_TYPE, AFTER_SAP_CODE, AFTER_SPEC_DESC, STOCK_AREA, CHANGE_TIME, CREATE_BY, CREATE_TIME, UPDATE_BY, UPDATE_TIME, DEL_FLAG, REMARK, DATA_VERSION) SELECT T.* FROM (
SELECT MOLD_BATCH_NO, LH_MACHINE_CODE, LH_MACHINE_NAME, BEFORE_SAP_CODE, BEFORE_SPEC_DESC, TIRE_ROUGH_STOCK, CHANGE_TYPE, AFTER_SAP_CODE, AFTER_SPEC_DESC, STOCK_AREA, CHANGE_TIME, CREATE_BY, CREATE_TIME, UPDATE_BY, UPDATE_TIME, DEL_FLAG, REMARK, #{dataVersion} DATA_VERSION FROM T_LH_MOLD_CHANGE_PLAN WHERE ID = #{id}
) T

mapper.update:
MERGE INTO T_LH_MOLD_CHANGE_PLAN A USING (
SELECT #{id} id FROM dual
) b ON (a.id = b.id) WHEN MATCHED THEN UPDATE SET IS_RELEASE = 1
